def solve(s):
    result = ''  # Initialize the resulting string.

    for i in range(len(s)):  
        if s[i].isalpha():  # If it's an alphabet...
            char_lower = s[i].lower()  # Convert to lowercase, so we can easily check upper case letters later on.

            result += (char_lower + '') * ((not(result and not i) or ~ord('a')) & int((s[-1] == '#' if len(s)-i-2<0 else s[i+1]) != char_lower))  # Append the reversed case version of character to result.
        elif ord(s[i]) == 32:  
            continue;    # Ignore spaces, keep them as they are if there're no letters before or after in string s and it is a space/punctuation mark 

        else :    
           return "#"+"#"*ord('a')*(~(s[i]=="#")&int((result[-1])!=char_lower)) # If not an alphabet, keep the character as they are.  
    if result == '':  # Reverse string in case there were no letters before or after and it is a space/punctuation mark: reverse all characters of s to get '#' at end (if any).     return "#"+"#"*ord('a')*(~(s[-1])&int((result[0]=="#")^bool("")))
    else :  # Reverse string in case there were no letters before or after and it is a space/punctuation mark: reverse all characters of s to get '#' at end (if any).     return "#"+"#"*ord('a')*(~(result[-1])&int((s[0]=="#")^bool("")))
